import React from 'react';
import { BrowserRouter, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Performance from './pages/Performance';
import ThreatModel from './pages/ThreatModel';

// Layout wrapper for authenticated pages
const AppLayout = ({ children }) => (
  <div className="flex h-screen bg-scifi-bg text-gray-300 font-mono overflow-hidden">
    <Sidebar />
    <div className="flex-1 overflow-auto custom-scrollbar">
      {children}
    </div>
  </div>
);

const PrivateRoute = ({ children }) => {
  const token = localStorage.getItem('token');
  return token ? <AppLayout>{children}</AppLayout> : <Navigate to="/" />;
};

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Login />} />
        <Route path="/dashboard" element={<PrivateRoute><Dashboard /></PrivateRoute>} />
        <Route path="/performance" element={<PrivateRoute><Performance /></PrivateRoute>} />
        <Route path="/threat-model" element={<PrivateRoute><ThreatModel /></PrivateRoute>} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
